<script setup>
import { computed, ref } from 'vue'
import { SHOPPING_STOREFRONT_EVENTS, SHOPPING_STOREFRONT_PROPS, localizeShoppingCopy } from './shopping-storefront-contract'
import Shopping29CmMedia from './Shopping29CmMedia.vue'
import { SHOPPING_29CM_ISSUES, shopping29cmEditorialSource, shopping29cmIssueSource, shopping29cmMediaSource, shopping29cmProductMedia, shopping29cmProductTone } from './shopping-29cm-media'

const props = defineProps(SHOPPING_STOREFRONT_PROPS)
const emit = defineEmits(SHOPPING_STOREFRONT_EVENTS)
const localize = (zh, en) => localizeShoppingCopy(props.languageBase, zh, en)
const editorialMode = ref('objects')
const issueIndexOpen = ref(false)
const selectedIssueIndex = ref(0)
const editorialModeOptions = Object.freeze([{ key: 'objects', zh: '物件', en: 'OBJECTS' }, { key: 'lookbook', zh: '图册', en: 'LOOKBOOK' }])
const activeIssue = computed(() => SHOPPING_29CM_ISSUES[selectedIssueIndex.value] || SHOPPING_29CM_ISSUES[0])
const leadProduct = computed(() => props.visibleProducts[0] || null)
const pairProducts = computed(() => props.visibleProducts.slice(1, 3))
const editorialProducts = computed(() => props.visibleProducts.slice(0, 3))
const productSource = (product, role = 'main') => props.productImageUrl(product) || shopping29cmMediaSource(shopping29cmProductMedia(product?.id, role))
const productTone = (product) => shopping29cmProductTone(product?.id)
const productAlt = (product, role = 'main') => props.productDisplayTitle(product) + ' / 29CM ' + role
const issueSource = computed(() => shopping29cmIssueSource(activeIssue.value?.id))
const editorialSource = (slot) => shopping29cmEditorialSource(slot)
const editorialTitle = computed(() => props.languageBase === 'zh' ? props.activeService?.heroZh || props.activeService?.zh || '日常之外' : props.activeService?.heroEn || props.activeService?.en || 'Beyond ordinary')
const setEditorialMode = (mode) => { editorialMode.value = mode; issueIndexOpen.value = false }
const setIssue = (index) => { selectedIssueIndex.value = index; issueIndexOpen.value = false }
</script>

<template>
  <main class="shopping-storefront-header shopping-29cm-app" :data-storefront="activeService?.storefrontTemplate || 'tech_catalog'" :data-editorial-mode="editorialMode" data-storefront-kind="marketplace">
    <header class="cm-masthead">
      <div class="cm-topbar">
        <button type="button" class="cm-back" data-testid="shopping-go-home" :aria-label="localize('返回主屏幕', 'Back to Home')" @click="emit('go-home')"><i class="fas fa-arrow-left" aria-hidden="true"></i></button>
        <div class="cm-wordmark"><span v-if="brandAssetUrl" class="cm-logo"><img :src="brandAssetUrl" alt="" /></span><span v-else class="cm-logo">29</span><div><p class="cm-overline">SEOUL / EDITION 29</p><h1>{{ activeLabel || activeService?.en || activeService?.zh || '29CM' }}</h1></div></div>
        <div class="cm-actions"><button type="button" class="cm-action" :aria-label="localize('收藏', 'Favorites')" @click="emit('open-favorites')"><i class="fas fa-heart" aria-hidden="true"></i><small v-if="favoriteCount">{{ favoriteCount }}</small></button><button type="button" class="cm-action" :aria-label="localize('选品袋', 'Selection bag')" @click="emit('open-cart')"><i class="fas fa-bag-shopping" aria-hidden="true"></i><small v-if="cartQuantity">{{ cartQuantity }}</small></button></div>
      </div>
      <nav class="cm-store-nav" :aria-label="localize('店内导航', 'Store navigation')"><button type="button" :class="{ 'is-active': !favoritesOnly }" @click="emit('show-all')"><span>01</span>{{ localize('本期', 'ISSUES') }}</button><button type="button" :class="{ 'is-active': favoritesOnly }" @click="emit('open-favorites')"><span>02</span>{{ localize('已保存', 'SAVED') }}</button><button type="button" @click="emit('open-cart')"><span>03</span>{{ localize('选品袋', 'SELECTION') }}<b v-if="cartQuantity">{{ cartQuantity }}</b></button><button type="button" @click="emit('open-orders')"><span>04</span>{{ localize('购买档案', 'ARCHIVE') }}<b v-if="orderCount">{{ orderCount }}</b></button></nav>
      <div class="cm-search-line"><label class="cm-search"><span>{{ localize('搜索', 'SEARCH') }}</span><input type="search" role="searchbox" :aria-label="localize('搜索商品', 'Search products')" :placeholder="localize('品牌、设计师和物件', 'Brands, designers, and objects')" :value="searchQuery" @input="emit('update:searchQuery', $event.target.value)" /><i class="fas fa-arrow-right" aria-hidden="true"></i></label><button type="button" class="cm-manage" :aria-label="localize('管理商品', 'Manage catalog')" @click="emit('open-manager')"><i class="fas fa-sliders" aria-hidden="true"></i></button></div>
    </header>

    <section class="cm-issue-stage" data-testid="shopping-29cm-issue-stage"><Shopping29CmMedia :src="issueSource" :alt="activeIssue.titleEn" :eyebrow="activeIssue.titleEn" :label="'ISSUE ' + String(selectedIssueIndex + 1).padStart(2, '0')" :tone="activeIssue.tone" role="issue" icon="fas fa-layer-group" /><div class="cm-issue-copy"><div class="cm-issue-copy-top"><span>{{ localize('第 ' + String(selectedIssueIndex + 1).padStart(2, '0') + ' 期 / 首尔', 'ISSUE ' + String(selectedIssueIndex + 1).padStart(2, '0') + ' / SEOUL') }}</span><span>2026</span></div><p class="cm-kicker">{{ localize('本期编辑精选', 'THE EDIT / CURRENT ISSUE') }}</p><h2>{{ languageBase === 'zh' ? activeIssue.titleZh : activeIssue.titleEn }}</h2><p class="cm-issue-note">{{ languageBase === 'zh' ? activeIssue.noteZh : activeIssue.noteEn }}</p><p v-if="mapReference?.placeId" class="cm-setting-reference" data-testid="shopping-map-reference" :data-map-place-id="mapReference.placeId"><i class="fas fa-location-dot" aria-hidden="true"></i><span>{{ localize('首尔场景锚点', 'SEOUL SETTING') }}</span><strong>{{ mapReference.district }}</strong></p><div class="cm-issue-copy-foot"><span>{{ editorialTitle }}</span><span>SCROLL TO EDIT</span></div></div></section>
    <section class="cm-issue-rail" aria-label="Issues"><button v-for="(issue, index) in SHOPPING_29CM_ISSUES" :key="issue.id" type="button" :class="{ 'is-active': index === selectedIssueIndex }" @click="setIssue(index)"><span class="cm-issue-rail-number">{{ String(index + 1).padStart(2, '0') }}</span><span><b>{{ languageBase === 'zh' ? issue.titleZh : issue.titleEn }}</b><small>{{ languageBase === 'zh' ? issue.noteZh : issue.noteEn }}</small></span><i class="fas fa-arrow-up-right-from-square" aria-hidden="true"></i></button></section>
    <section class="cm-editorial-tools"><div class="cm-mode-switch" role="tablist" :aria-label="localize('编辑视图', 'Editorial view')"><button v-for="mode in editorialModeOptions" :key="mode.key" type="button" class="cm-mode-button" :class="{ 'is-active': editorialMode === mode.key }" role="tab" :aria-selected="editorialMode === mode.key" :data-testid="'shopping-29cm-mode-' + mode.key" @click="setEditorialMode(mode.key)">{{ localize(mode.zh, mode.en) }}</button></div><button type="button" class="cm-issue-toggle" :aria-expanded="issueIndexOpen" data-testid="shopping-29cm-issue-toggle" @click="issueIndexOpen = !issueIndexOpen"><span>{{ localize('本期目录', 'ISSUE INDEX') }}</span><i :class="issueIndexOpen ? 'fas fa-minus' : 'fas fa-plus'" aria-hidden="true"></i></button></section>
