gle-favorite', product.id)"><i class="fas fa-heart" aria-hidden="true"></i></button></div><div class="cm-shelf-copy"><span>{{ props.productServiceLabel(product) }}</span><h3><button type="button" @click="emit('open-product', product.id)">{{ props.productDisplayTitle(product) }}</button></h3><p>{{ props.productDisplayDescription(product) }}</p><div class="cm-shelf-meta"><strong>{{ props.formatPrice(product) }}</strong><span :class="props.stockStatusClass(product.stockStatus)">{{ props.stockStatusLabel(product.stockStatus) }}</span></div><button type="button" class="cm-add" :disabled="product.stockStatus === 'sold_out'" :data-testid="'shopping-add-cart-' + product.id" @click="emit('add-to-cart', product.id)">{{ localize('加入选品袋', 'ADD TO BAG') }} <i class="fas fa-arrow-up-right-from-square" aria-hidden="true"></i></button></div></article></div></section>
  </main>
